[
  {
    "statement": "Restoring wetlands often produced amphibian abundance and species richness similar to that of natural wetlands in multiple North American studies.",
    "citations": [
      "879"
    ]
  },
  {
    "statement": "Additional studies on wetland restoration have shown increases in amphibian species numbers and colonization.",
    "citations": [
      "879"
    ]
  },
  {
    "statement": "Some cases of wetland restoration found lower amphibian species richness or had mixed effects.",
    "citations": [
      "879"
    ]
  },
  {
    "statement": "The outcomes of wetland restoration for amphibians varied with the wetland's size, its proximity to amphibian sources, and seasonality.",
    "citations": [
      "879"
    ]
  },
  {
    "statement": "Pond restoration for amphibians showed mixed results that varied by species and site.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Several studies on pond restoration reported increased amphibian species numbers, population maintenance or increases, and colonization.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Pond restoration has resulted in more ponds being used for amphibian breeding.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Other studies on pond restoration found no increase or had inconclusive outcomes for certain amphibian species.",
    "citations": [
      "878"
    ]
  },
  {
    "statement": "Restoring or retaining connectivity by elevating a road to reconnect wetlands reduced amphibian road mortality.",
    "citations": [
      "840",
      "853"
    ]
  },
  {
    "statement": "Retaining native vegetation corridors maintained multiple frog species over a period of decades.",
    "citations": [
      "840",
      "853"
    ]
  },
  {
    "statement": "Managing water levels in habitats increased or maintained certain toad and newt populations.",
    "citations": [
      "833"
    ]
  },
  {
    "statement": "Managing water levels enabled successful breeding in a threatened frog species.",
    "citations": [
      "833"
    ]
  },
  {
    "statement": "In one study, draining ponds increased amphibian abundance and the number of amphibian species.",
    "citations": [
      "833"
    ]
  },
  {
    "statement": "Engaging landowners and volunteers in restoration efforts was associated with population increases in some amphibian species.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Engaging landowners and volunteers was associated with increased amphibian weights in aquatically managed habitats.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Large-scale restoration efforts have involved thousands of volunteers and resulted in up to 1,023 ponds restored or over 11,500 km2 of habitat managed.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Payments to farmers to cover conservation costs created breeding habitat for amphibians in several countries.",
    "citations": [
      "818"
    ]
  },
  {
    "statement": "Payments to farmers for conservation increased frog and toad populations.",
    "citations": [
      "818"
    ]
  },
  {
    "statement": "Ditches managed under agri-environment schemes were associated with higher amphibian species numbers and abundance compared to conventionally managed ditches.",
    "citations": [
      "818"
    ]
  },
  {
    "statement": "In some contexts, replanting or reseeding vegetation led to amphibian communities similar to those in natural sites.",
    "citations": [
      "849"
    ]
  },
  {
    "statement": "In one case, replanting vegetation increased frog species and led to colonization of the restored habitats.",
    "citations": [
      "849"
    ]
  },
  {
    "statement": "Post-logging planted forests treated with herbicide had lower or similar amphibian abundance than naturally regenerating forests, depending on the species and age of the forest.",
    "citations": [
      "849"
    ]
  },
  {
    "statement": "Reduced mowing as a part of restoration was linked to an increased number of frog species in one study.",
    "citations": [
      "783"
    ]
  },
  {
    "statement": "Grazing management for amphibian habitat yielded mixed outcomes.",
    "citations": [
      "780"
    ]
  },
  {
    "statement": "Some grazing management programs increased or maintained populations of certain toads.",
    "citations": [
      "780"
    ]
  },
  {
    "statement": "Other grazing management programs found no advantage or resulted in lower amphibian abundance, depending on the species and grazing regime.",
    "citations": [
      "780"
    ]
  }
]

[
  {
    "statement": "There is no evidence for the effects of planting new hedges on amphibian populations.",
    "citations": [
      "791"
    ]
  },
  {
    "statement": "There is no evidence for the effects of maintaining or restoring hedges on amphibian populations.",
    "citations": [
      "790"
    ]
  }
]

[
  {
    "statement": "The action document reports no evidence for the effects of reduced tillage on amphibian populations.",
    "citations": [
      "789"
    ]
  },
  {
    "statement": "No studies were found that directly and quantitatively tested the action of reduced tillage on amphibian populations.",
    "citations": [
      "789"
    ]
  },
  {
    "statement": "The effectiveness or potential harmful impacts of reduced tillage on amphibians cannot be assessed.",
    "citations": [
      "789"
    ]
  }
]

[
  {
    "statement": "The available evidence base reports no studies directly evaluating whether commercially breeding amphibians for the pet trade affects wild amphibian populations.",
    "citations": [
      "794"
    ]
  },
  {
    "statement": "A review reported that legislation reducing trade in two frog species allowed recovery of populations that had been over-exploited.",
    "citations": [
      "824",
      "785"
    ]
  },
  {
    "statement": "For reptiles, one study in the Cayman Islands found that where a commercial turtle farm operated, consumption and purchase of wild turtle products was rare.",
    "citations": [
      "3539"
    ]
  },
  {
    "statement": "The study in the Cayman Islands also found that some residents still preferred wild meat.",
    "citations": [
      "3539"
    ]
  },
  {
    "statement": "The evidence base also notes no studies evaluating the effects of using amphibians sustainably.",
    "citations": [
      "793"
    ]
  }
]

[
  {
    "statement": "Naturally colonizing, captive-bred, and translocated great crested newts established breeding populations at 57–75% of created ponds or sites.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "Up to 88% of created ponds were colonized by translocated or naturally colonizing great crested newts.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "Head-started great crested newts reproduced in 38% of created ponds.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "A systematic review in the UK found no conclusive evidence that mitigation, which often included pond creation, resulted in self-sustaining populations.",
    "citations": [
      "863"
    ]
  },
  {
    "statement": "For salamanders including newts, studies found that stable breeding populations were established in 20–100% of created ponds.",
    "citations": [
      "867"
    ]
  },
  {
    "statement": "For salamanders including newts, reproduction was reported in 60–100% of created ponds across several species.",
    "citations": [
      "867"
    ]
  },
  {
    "statement": "For translocations of great crested newts, four of six studies found that breeding populations were maintained or established.",
    "citations": [
      "858"
    ]
  },
  {
    "statement": "One review found that reproduction followed 56% of great crested newt translocations.",
    "citations": [
      "858"
    ]
  },
  {
    "statement": "In one study, great crested newt breeding failed in 48% of ponds within three years.",
    "citations": [
      "858"
    ]
  },
  {
    "statement": "A systematic review found no conclusive evidence that mitigation including translocations of great crested newts resulted in self-sustaining populations.",
    "citations": [
      "858"
    ]
  }
]

[
  {
    "statement": "There is no evidence available on the effects of planting new hedges on amphibian populations.",
    "citations": [
      "791"
    ]
  }
]

[
  {
    "statement": "Two studies summarized in an action document on closing roads during seasonal amphibian migration in Germany reported that large numbers of amphibians were protected from death at road closure sites.",
    "citations": ["842"]
  },
  {
    "statement": "Road closure sites protecting amphibians included sites with assisted crossings and barrier fences.",
    "citations": ["842"]
  },
  {
    "statement": "An action document on closing roads during seasonal amphibian migration in Germany does not assess the impacts of traffic noise on breeding success outcomes.",
    "citations": ["842"]
  },
  {
    "statement": "An action document on reducing noise pollution by restricting development activities reports that no studies were found that directly and quantitatively tested the effects of this action.",
    "citations": ["1562"]
  },
  {
    "statement": "The evidence noted in an action document on reducing noise pollution pertains to primates rather than amphibians.",
    "citations": ["1562"]
  }
]
